def replay_label_artwork(crop,complete):
  """Fixed replay labels have a stable glyph shape even when Korean OCR says ㅇK.

    Called only inside a visually confirmed pair of replay buttons. This does
    not lower OCR thresholds or accept the button colour as label evidence.
    """
  import cv2,base64
  key='quit' if complete else 'ok';reference=REPLAY_LABEL_ARTWORK[key]
  rgb=np.asarray(crop.convert('RGB'),dtype=np.int16)
  mask=((rgb.max(axis=2)-rgb.min(axis=2)<30)&((rgb.max(axis=2)<180) if complete else (rgb.min(axis=2)>225))).astype('uint8')
  _,labels,stats,_=cv2.connectedComponentsWithStats(mask,8)
  keep=[i for i,(_,_,w,h,area) in enumerate(stats[1:],1) if w>=2 and h>=2 and area>=6]
  decision=dict(confirmed=False,source='replay_label_artwork',label='그만두기' if complete else 'OK')
  if not keep:return decision
  ys,xs=np.nonzero(np.isin(labels,keep));x,y,u,v=int(xs.min()),int(ys.min()),int(xs.max()+1),int(ys.max()+1)
  aspect=(u-x)/(v-y);delta=abs(aspect-reference['aspect'])/reference['aspect']
  if delta>.12 or not .35<=((x+u)/2)/crop.width<=.65 or not .30<=((y+v)/2)/crop.height<=.85:return decision
  shape=reference['shape'];actual=cv2.resize(mask[y:v,x:u],(shape[1],shape[0]),interpolation=cv2.INTER_NEAREST)>0
  expected=np.unpackbits(np.frombuffer(base64.b85decode(reference['bits']),dtype=np.uint8))[:shape[0]*shape[1]].reshape(shape)>0
  union=np.logical_or(actual,expected).sum();overlap=float(np.logical_and(actual,expected).sum()/union) if union else 0
  decision.update(confirmed=overlap>=.92,glyph_iou=round(overlap,6),aspect_delta=round(delta,6),glyph_box=[x,y,u,v])
  return decision
def _held_jammer_artwork(before,frame,rect,source,destination,refine_subpixel=False):
  """Match a translucent held jammer to its actual pre-drag eyes and silhouette."""
  import cv2
  if not isinstance(before,Image.Image) or before.size!=frame.size:return None
  x,y,w,h=rect;cw,ch=w/6,h/5
  sx=x+(source%6+.5)*cw;sy=y+(source//6+.5)*ch
  cx=x+(destination%6+.5)*cw;cy=y+(destination//6+.5)*ch
  def broad(image,px,py,scale,extent=.50):
    box=(round(px-extent*cw*scale),round(py-extent*ch*scale),round(px+extent*cw*scale),round(py+extent*ch*scale))
    if box[0]<0 or box[1]<0 or box[2]>image.width or box[3]>image.height:return None
    return np.asarray(image.crop(box).convert('RGB').resize((64,64),Image.Resampling.BILINEAR))
  if sum(classify_cell(broad(before,sx,sy,1,extent))[0]=='J' for extent in (.30,.40,.46))<2:return None
  def eyes(pixels):
    red,green,blue=(pixels[:,:,i].astype(np.int16) for i in range(3))
    mask=((red>95)&(green>95)&(np.minimum(red,green)-blue>20)&(np.abs(red-green)<80)).astype('uint8')
    _,labels,stats,centers=cv2.connectedComponentsWithStats(mask,8);pairs=[[],[]]
    for component,(a,b,w,h,area) in enumerate(stats[1:],1):
      ex,ey=map(float,centers[component])
      if not (5<=w<=18 and 3<=h<=12 and 1.3<=w/h<=5 and 10<=area<=140 and .20<=area/(w*h)<=.80 and 10<=ey<=32):continue
      side=0 if 3<=ex<=16 else 1 if 24<=ex<=37 else None
      if side is None:continue
      shape=cv2.resize((labels[b:b+h,a:a+w]==component).astype('uint8'),(20,12),interpolation=cv2.INTER_NEAREST)>0
      pairs[side].append(dict(center=(ex,ey),area=int(area),shape=shape))
    if any(len(side)!=1 for side in pairs):return None
    left,right=(side[0] for side in pairs)
    return (left,right) if abs(left['center'][1]-right['center'][1])<=2 else None
  def silhouette(pixels):
    hue,sat,value=rgb_to_hsv_np(pixels)
    return (hue>=185)&(hue<=255)&(sat>.18)&(value<.65)
  template=_touch_start_artwork_patch(before,sx,sy,cw,ch);reference_eyes=eyes(template)
  if reference_eyes is None:return _held_jammer_complete_artwork(before,frame,rect,source,destination,refine_subpixel)
  reference_shape=silhouette(broad(before,sx,sy,1))
  centered=template-template.mean(axis=(0,1),keepdims=True);norm=float(np.linalg.norm(centered));choices=[]
  for dx in (-.20,-.15,-.10,-.05,0,.05,.10,.15,.20):
    for offset in (.18,.22,.26,.30,.34,.38,.42,.48,.54,.60,.66,.72,.78,.84):
      for scale in (1.0,1.08,1.16,1.24):
        pixels=_touch_start_artwork_patch(frame,cx+dx*cw,cy-offset*ch,cw,ch,scale)
        error=float(np.abs(pixels-template).mean()/255)
        shifted=pixels-pixels.mean(axis=(0,1),keepdims=True);denominator=norm*float(np.linalg.norm(shifted))
        correlation=float(np.sum(centered*shifted)/denominator) if denominator else 0
        if correlation>=.70 and error<=.16:choices.append((correlation,error,dx,offset,scale,pixels))
  for correlation,error,dx,offset,scale,pixels in sorted(choices,key=lambda row:(-row[0],row[1])):
    selected_eyes=eyes(pixels)
    if selected_eyes is None:continue
    eye_matches=[]
    for one,two in zip(reference_eyes,selected_eyes):
      delta=max(abs(a-b) for a,b in zip(one['center'],two['center']));ratio=two['area']/one['area']
      overlap=float(np.logical_and(one['shape'],two['shape']).sum()/np.logical_or(one['shape'],two['shape']).sum())
      if delta>3 or not .60<=ratio<=1.60 or overlap<.70:break
      eye_matches.append(dict(center_delta=round(delta,5),area_ratio=round(ratio,5),shape_iou=round(overlap,5)))
    if len(eye_matches)!=2:continue
    selected=broad(frame,cx+dx*cw,cy-offset*ch,scale)
    if selected is None:continue
    model_reading=ai_core.jammer_water_predict([Image.fromarray(selected)])[0]
    if model_reading['code']=='B':continue
    shape=silhouette(selected);union=np.logical_or(reference_shape,shape).sum()
    overlap=float(np.logical_and(reference_shape,shape).sum()/union) if union else 0
    if not .20<=float(shape.mean())<=.65 or overlap<.68:continue
    return dict(held_artwork_kind='jammer_paired_eyes_and_silhouette',held_eye_matches=eye_matches,
held_jammer_water_model=model_reading,
held_silhouette_iou=round(overlap,5),held_match_correlation=round(correlation,5),held_match_mae=round(error,5),
held_lift_x_offset=dx,held_lift_offset=offset,held_lift_scale=scale)
  return _held_jammer_complete_artwork(before,frame,rect,source,destination,refine_subpixel)
def _held_jammer_complete_artwork(before,frame,rect,source,destination,refine_subpixel=False):
  """Match both complete eyes when the old central reference clips an eye."""
  if not isinstance(before,Image.Image) or before.size!=frame.size:return None
  x,y,w,h=rect;cw,ch=w/6,h/5
  sx=x+(source%6+.5)*cw;sy=y+(source//6+.5)*ch
  cx=x+(destination%6+.5)*cw;cy=y+(destination//6+.5)*ch
  def artwork(image,px,py,scale,extent):
    box=(round(px-extent*cw*scale),round(py-extent*ch*scale),round(px+extent*cw*scale),round(py+extent*ch*scale))
    if box[0]<0 or box[1]<0 or box[2]>image.width or box[3]>image.height:return None
    return np.asarray(image.crop(box).convert('RGB').resize((64,64),Image.Resampling.BILINEAR))
  resting=[artwork(before,sx,sy,1,e) for e in (.30,.40,.46)]
  if sum(tile is not None and classify_cell(tile)[0]=='J' for tile in resting)<2:return None
  source_eyes=None
  for face_extent in (.38,.46):
    reference=artwork(before,sx,sy,1,face_extent)
    if reference is not None:source_eyes=_jammer_complete_eye_pair(reference)
    if source_eyes is not None:break
  if source_eyes is None:return None
  def navy(pixels):
    hue,sat,value=rgb_to_hsv_np(pixels)
    return (hue>=185)&(hue<=255)&(sat>.18)&(value<.65)
  reference_shape=navy(artwork(before,sx,sy,1,.50))
  for correlation,error,dx,offset,scale,alpha,residual,translucent,bias in jammer_texture_poses(before,frame,rect,source,destination,_touch_start_artwork_patch,refine_subpixel=refine_subpixel):
    px,py=cx+dx*cw,cy-offset*ch
    selected=artwork(frame,px,py,scale,face_extent);old=artwork(before,px,py,scale,face_extent)
    if selected is None or old is None:continue
    selected_eyes=_jammer_complete_eye_pair(selected)
    if selected_eyes is None:continue
    fresh=jammer_changed_eye_pixels(old,selected);matches=[]
    for one,two in zip(source_eyes,selected_eyes):
      delta=max(abs(a-b) for a,b in zip(one['center'],two['center']));ratio=two['area']/one['area']
      iou=float(np.logical_and(one['shape'],two['shape']).sum()/np.logical_or(one['shape'],two['shape']).sum())
      new=float(fresh[two['mask']].mean())
      if delta>3 or not .60<=ratio<=1.60 or iou<.75 or new<.50:break
      matches.append(dict(center_delta=round(delta,5),area_ratio=round(ratio,5),shape_iou=round(iou,5),new_eye_fraction=round(new,5)))
    if len(matches)!=2:continue
    broad=artwork(frame,px,py,scale,.50)
    if broad is None:continue
    model=ai_core.jammer_water_predict([Image.fromarray(broad)])[0]
    if model['code']=='B':continue
    shape=navy(broad);union=np.logical_or(reference_shape,shape).sum()
    iou=float(np.logical_and(reference_shape,shape).sum()/union) if union else 0
    compensation=None
    if not .20<=float(shape.mean())<=.65 or iou<.68:
      if not translucent:continue
      restored=np.clip((broad.astype(np.float32)-bias)/alpha,0,255).astype(np.uint8)
      restored_model=ai_core.jammer_water_predict([Image.fromarray(restored)])[0]
      if restored_model['code']!='J':continue
      compensated=navy(restored);union=np.logical_or(reference_shape,compensated).sum()
      compensated_iou=float(np.logical_and(reference_shape,compensated).sum()/union) if union else 0
      if not .20<=float(compensated.mean())<=.65 or compensated_iou<.68:continue
      compensation=dict(raw_silhouette_iou=round(iou,5),restored_silhouette_iou=round(compensated_iou,5),model=restored_model)
      iou=compensated_iou
    return dict(held_artwork_kind='jammer_complete_eyes_and_silhouette',held_eye_matches=matches,
held_jammer_water_model=model,held_silhouette_iou=round(iou,5),
held_match_correlation=round(correlation,5),held_match_mae=round(error,5),
held_face_extent=face_extent,held_texture_alpha=round(alpha,5),held_texture_residual=round(residual,5),
held_appearance_compensation=compensation,
held_lift_x_offset=dx,held_lift_offset=offset,held_lift_scale=scale)
  return None
def sdk_held_board_verification(frame,board,path,observed,trace,diagnostics,rect=(882,255,692,572),cloud_mask=None,before_frame=None,master=False):
  """Validate an SDK layout without treating the lifted final orb as its cell.

    A lifted orb is only provisional evidence. The caller must still observe
    the existing post-UP game reaction before marking the move successful.
    """
  result=dict(confirmed=False,mismatch_cells=[],occluded_cell=None)
  if observed is None or len(observed)!=30 or len(board)!=30 or not manual_route_supported(path):
    result['reason']='board_unavailable';return result
  expected=board_after_drag(board,path);hidden=[False]*30
  if cloud_mask is not None and any(cloud_mask):
    if len(cloud_mask)!=30 or any(type(value) is not bool for value in cloud_mask):
      result['reason']='cloud_mask_unconfirmed';return result
    x,y,w,h=rect;crop=frame.crop((x,y,x+w,y+h));physical=obscured_cell_mask(crop)
    if any(physical[i] and not cloud_mask[i] for i in range(30)) or not cloud_visible_board_valid(crop,observed,physical):
      result['reason']='cloud_visible_grid_unconfirmed';return result
    hidden=[bool(physical[i] and cloud_mask[i]) for i in range(30)]
  mismatch=[i for i,(a,b) in enumerate(zip(observed,expected)) if a!=b and not hidden[i]]
  result['mismatch_cells']=mismatch
  result['cloud_cells_unverified']=[i for i,value in enumerate(hidden) if value]
  if not mismatch and not any(hidden):
    result.update(confirmed=True,reason='exact_layout');return result
  proofs=stationary_occlusion_proofs(before_frame,frame,rect,board,path,observed,classify_board,board_after_drag) if master else {}
  if proofs:
    result.update(raw_mismatch_cells=list(mismatch),source_texture_proofs=list(proofs.values()))
    mismatch=[i for i in mismatch if i not in proofs];result['mismatch_cells']=mismatch
  cursor=path[-1];held=board[path[0]]
  if mismatch not in ([],[cursor]) or ((mismatch or proofs) and (held not in ('R','B','G','Y','P','H','J') or expected[cursor]!=held)):
    result['reason']='layout_mismatch';return result
  control=isinstance(diagnostics,dict) and (diagnostics.get('input_transport') in ('android_control','android_verified_batch') or str(diagnostics.get('input_transport','')).startswith('maa_'))
  if not isinstance(diagnostics,dict) or diagnostics.get('control_dispatch_confirmed' if control else 'sdk_dispatch_confirmed') is not True or diagnostics.get('control_release_confirmed' if control else 'sdk_release_confirmed') is not True:
    result['reason']='sdk_delivery_unconfirmed';return result
  size=diagnostics.get('input_size')
  if not isinstance(size,(tuple,list)) or len(size)!=2 or any(type(v) is not int or v<=0 for v in size):
    result['reason']='sdk_size_unavailable';return result
  starts=[i for i,event in enumerate(trace) if event.get('action')==0]
  events=trace[starts[-1]:] if starts else []
  x,y,w,h=rect
  points=[(min(size[0]-1,round((x+(i%6+.5)*w/6)*size[0]/1600)),
min(size[1]-1,round((y+(i//6+.5)*h/5-40)*size[1]/900))) for i in path]
  samples=[points[0]]
  for one,two in zip(points,points[1:]):
    samples.extend((round(one[0]+(two[0]-one[0])*part/4),round(one[1]+(two[1]-one[1])*part/4)) for part in range(1,5))
  samples.append(points[-1]);actions=[0]+[2]*(len(samples)-2)+[1]
  valid=len(events)==len(samples)
  if valid:
    for event,point,action in zip(events,samples,actions):
      native=event.get('native')
      if (event.get('action')!=action or event.get('finger_id')!=(0 if control or diagnostics.get('sdk_input_stream')=='single_pointer' else 1) or event.get('transport')!=(diagnostics.get('input_transport') if control else 'mumu_native_sdk')
or not isinstance(native,(list,tuple)) or len(native)!=2
or any(type(value) is not int or abs(value-wanted)>1 for value,wanted in zip(native,point))):
        valid=False;break
  if not valid:
    result['reason']='sdk_path_unconfirmed';return result
  if not mismatch and not proofs:
    result.update(confirmed=True,reason='cloud_visible_layout');return result
  if held=='J':
    proof=_held_jammer_artwork(before_frame,frame,rect,path[0],cursor,refine_subpixel=master)
    if proof is None:
      result.update(reason='held_jammer_unconfirmed',held_color=held);return result
    result.update(proof,confirmed=True,reason='cloud_visible_layout' if any(hidden) else 'lifted_final_orb',
held_color=held,occluded_cell=cursor)
    return result
  cw,ch=w/6,h/5;cx=x+(cursor%6+.5)*cw;cy=y+(cursor//6+.5)*ch
  codes=[]
  for offset in (.25,.30):
    box=(round(cx-cw*.22),round(cy-ch*(offset+.22)),round(cx+cw*.22),round(cy-ch*(offset-.22)))
    if box[0]<0 or box[1]<0 or box[2]>frame.width or box[3]>frame.height:
      result['reason']='held_orb_outside_capture';return result
    codes.append(classify_cell(np.asarray(frame.convert('RGB').crop(box)))[0])
  result.update(held_color=held,floating_codes=codes)
  if codes!=[held,held]:
    if held=='P':
      proof=lifted_colour_texture(before_frame,frame,rect,path[0],cursor,held,classify_cell,_curved_spike_overlay)
      if proof is None:
        proof=lifted_colour_texture(before_frame,frame,rect,path[0],cursor,held,classify_cell,_curved_spike_overlay,background=True)
      if proof is not None:
        result.update({'held_'+key:value for key,value in proof.items()},confirmed=True,
reason='cloud_visible_layout' if any(hidden) else 'lifted_final_orb',occluded_cell=cursor)
        return result
    result['reason']='held_orb_unconfirmed';return result
  result.update(confirmed=True,reason='cloud_visible_layout' if any(hidden) else 'lifted_final_orb',occluded_cell=cursor)
  return result
def background_entry_card_rects(frame):
  """Resolve each card separately; the entry row uses a narrower pitch than battle."""
  rgb=np.asarray(frame.convert('RGB'));band=rgb[240:380,70:930].astype('int16')
  fallback=[(94+136*i,228,226+136*i,450) for i in range(6)]
  if band.shape[:2]!=(140,860):return fallback
  white=(band.min(axis=2)>210)&(band.max(axis=2)-band.min(axis=2)<45)
  ink=(1-white.mean(axis=0))>.25
  for i in range(1,len(ink)-2):
    if ink[i-1] and ink[i+1]:ink[i]=True
  edges=np.diff(np.r_[False,ink,False].astype('int8'));runs=list(zip(np.where(edges==1)[0]+70,np.where(edges==-1)[0]+70))
  result=[]
  for slot in range(6):
    center=158+136*slot
    candidates=[(x0,x1) for x0,x1 in runs if x0<=center<x1 and 105<=x1-x0<=140]
    if len(candidates)!=1:return fallback
    x0,x1=candidates[0];result.append((max(0,int(x0)-3),228,min(frame.width,int(x1)+3),450))
  if any(result[i][2]>=result[i+1][0] for i in range(5)):return fallback
  return result
def show_game_overlay_without_focus(window):
  """An independent top-level remains visible while the main Tk window is minimized."""
  if sys.platform!='win32':
    if window.state()=='withdrawn':window.deiconify()
    window.attributes('-topmost',True);window.lift();return
  from ctypes import wintypes
  api=ctypes.windll.user32
  api.GetAncestor.argtypes=(wintypes.HWND,wintypes.UINT);api.GetAncestor.restype=wintypes.HWND
  hwnd=api.GetAncestor(window.winfo_id(),2) or window.winfo_id()
  get_long=getattr(api,'GetWindowLongPtrW',api.GetWindowLongW)
  set_long=getattr(api,'SetWindowLongPtrW',api.SetWindowLongW)
  get_long.argtypes=(wintypes.HWND,ctypes.c_int);get_long.restype=ctypes.c_ssize_t
  set_long.argtypes=(wintypes.HWND,ctypes.c_int,ctypes.c_ssize_t);set_long.restype=ctypes.c_ssize_t
  set_long(hwnd,-8,0)
  set_long(hwnd,-20,get_long(hwnd,-20)|0x08000000|0x00000080)
  if window.state()=='withdrawn':window.deiconify()
  hwnd=api.GetAncestor(window.winfo_id(),2) or window.winfo_id()
  set_long(hwnd,-8,0)
  set_long(hwnd,-20,get_long(hwnd,-20)|0x08000000|0x00000080)
  api.SetWindowPos.argtypes=(wintypes.HWND,wintypes.HWND,ctypes.c_int,ctypes.c_int,ctypes.c_int,ctypes.c_int,wintypes.UINT)
  api.SetWindowPos.restype=wintypes.BOOL
  if not api.SetWindowPos(hwnd,wintypes.HWND(-1),0,0,0,0,0x53):raise OSError('오버레이 표시 실패')
def background_portrait(frame,slot,entry=False,size=(16,20)):
  if entry:
    x0,_,x1,_=background_entry_card_rects(frame)[slot]
    return np.asarray(frame.crop((x0+18,260,x1-18,350)).resize(size,Image.Resampling.BILINEAR),dtype=np.int16)
  x=.018+.0875*slot;y=.700
  crop=frame.crop((round((x+.016)*1600),round((y+.032)*940),round((x+.063)*1600),round((y+.126)*940)))
  return np.asarray(crop.resize(size,Image.Resampling.BILINEAR),dtype=np.int16)
def background_party_portrait_matches(reference,current):
  return party_portrait_matches(reference,current)
def background_party_identity_checks(profiles,frame,master=False,entry_frame=None):
  bound=background_bound_slots(frame) if master else ()
  rows=party_identity_checks(profiles,frame,background_portrait,bound_slots=bound)
  if not bound or not isinstance(entry_frame,Image.Image) or entry_frame.size!=(1600,940):return rows
  measured_entry=None
  if any(0<=slot<len(profiles) and profiles[slot].get('portrait_image_version')==5 for slot in bound):
    layout=party_card_layout(entry_frame)
    if layout is not None:measured_entry=normalized_party_cards(entry_frame,layout)
  for slot in bound:
    if not 0<=slot<len(rows):continue
    row=rows[slot];profile=profiles[slot]
    source_entry=entry_frame
    if profile.get('portrait_image_version')==5:
      if measured_entry is None:
        row.pop('bound_identity_proof',None);row.pop('identity_method',None)
        row.update(matched=False,bound_identity_diagnostics=dict(accepted=False,reason='entry_card_layout_unavailable'));continue
      source_entry=measured_entry
    current=background_portrait(source_entry,slot,entry=True)
    reference=np.asarray(profile['portrait'],dtype=np.float32)
    error=float(np.abs(current-reference).mean()) if current.shape==reference.shape else None
    diagnostics=dict(entry_reference_difference=round(error,3) if error is not None else None)
    proof=None
    if error is not None and np.isfinite(error) and error<=8:
      proof=bound_entry_portrait_proof(background_portrait(source_entry,slot,True,size=(80,100)),
background_portrait(frame,slot,size=(80,100)),diagnostics)
    else:diagnostics.update(accepted=False,reason='entry_reference_mismatch')
    row.pop('bound_identity_proof',None);row.pop('identity_method',None)
    row.update(matched=proof is not None,bound_identity_diagnostics=diagnostics)
    if proof is not None:row.update(identity_method='fresh_entry_bound_texture',bound_identity_proof=proof)
  return rows
def background_challenge_text_boxes(frame):
  """Find white label lines without assuming the challenge button's color."""
  import cv2
  if frame.size!=(1600,940):return []
  rgb=np.asarray(frame.convert('RGB'));left,top=1150,610
  white=(rgb[top:895,left:1590].min(axis=2)>215).astype('uint8')
  _,_,stats,_=cv2.connectedComponentsWithStats(white,8)
  glyphs=[(int(x+left),int(y+top),int(w),int(h)) for x,y,w,h,count in stats[1:] if 4<=w<=60 and 12<=h<=65 and count>=12]
  lines=[]
  for glyph in sorted(glyphs,key=lambda g:g[1]+g[3]/2):
    cy=glyph[1]+glyph[3]/2
    if lines and abs(cy-sum(g[1]+g[3]/2 for g in lines[-1])/len(lines[-1]))<=12:lines[-1].append(glyph)
    else:lines.append([glyph])
  boxes=[]
  for line in lines:
    x0=min(x for x,y,w,h in line);y0=min(y for x,y,w,h in line);x1=max(x+w for x,y,w,h in line);y1=max(y+h for x,y,w,h in line)
    if 3<=len(line)<=12 and 65<=x1-x0<=300 and 12<=y1-y0<=70:boxes.append((x0-3,y0-3,x1+3,y1+3))
  return boxes[:5]
def background_challenge_button(frame):
  import cv2
  if frame.size!=(1600,940):return None
  rgb=np.asarray(frame.convert('RGB'));ox,oy=1100,600;area=rgb[oy:930,ox:1600]
  hsv=cv2.cvtColor(area,cv2.COLOR_RGB2HSV)
  mask=((hsv[...,0]>=8)&(hsv[...,0]<=40)&(hsv[...,1]>140)&(hsv[...,2]>180)).astype('uint8')
  _,_,stats,_=cv2.connectedComponentsWithStats(mask,8);found=[]
  for x,y,w,h,count in stats[1:]:
    if not (150<w<490 and 45<h<300 and count>w*h*.55):continue
    box=(int(x+ox),int(y+oy),int(x+ox+w),int(y+oy+h))
    left,top=round(box[0]+.12*w),round(box[1]+.18*h)
    right,bottom=round(box[2]-.12*w),round(box[3]-.18*h)
    white=(rgb[top:bottom,left:right].min(axis=2)>215).astype('uint8')
    _,_,letters,_=cv2.connectedComponentsWithStats(white,8)
    letters=[(a,b,c,d) for a,b,c,d,count in letters[1:] if count>=6 and d>=8]
    if not letters:continue
    text_box=(max(left,min(a for a,b,c,d in letters)+left-3),max(top,min(b for a,b,c,d in letters)+top-3),min(right,max(a+c for a,b,c,d in letters)+left+3),min(bottom,max(b+d for a,b,c,d in letters)+top+3))
    found.append((box,text_box))
  return found[0] if len(found)==1 else None
def background_skill_popup_stability(before,after,target=None):
  """Compare measured Use geometry, not the inferred Close box/glowing edge.

    Coordinates are normalized screenshot pixels. A pulsing highlight may
    resize the contour while its center and the intended inner hit stay put.
    This verifies observable geometry only, not Android/game touch state.
    """
  result=dict(stable=False,before=before,after=after,target=target,
coordinate_scope='normalized_frame_pixels')
  if before is None or after is None:
    result.update(stable=before is None and after is None,
reason='no_popup' if before is None and after is None else 'popup_presence_changed')
    return result
  old,new=before[1],after[1]
  sizes=[(box[2]-box[0],box[3]-box[1]) for box in (old,new)]
  centers=[((box[0]+box[2])/2,(box[1]+box[3])/2) for box in (old,new)]
  delta=[centers[1][i]-centers[0][i] for i in (0,1)]
  result.update(use_centers=centers,use_center_delta=delta,use_sizes=sizes)
  if any(value<=0 for size in sizes for value in size):
    result['reason']='invalid_button_size';return result
  if max(abs(value) for value in delta)>4:
    result['reason']='use_center_moved';return result
  if any(abs(sizes[1][i]-sizes[0][i])/sizes[0][i]>.20 for i in (0,1)):
    result['reason']='use_size_changed';return result
  inner=[(box[0]+w*.20,box[1]+h*.20,box[2]-w*.20,box[3]-h*.20)
for box,(w,h) in zip((old,new),sizes)]
  result['shared_safe_interior']=[max(box[0] for box in inner),max(box[1] for box in inner),
min(box[2] for box in inner),min(box[3] for box in inner)]
  if target is not None:
    x,y=target;l,t,r,b=result['shared_safe_interior']
    if not (l<x<r and t<y<b):
      result['reason']='target_outside_shared_interior';return result
  result.update(stable=True,reason='use_center_and_safe_interior_stable')
  return result
def background_skill_button_rects(frame):
  """Find the orange use button and adjacent white close button, left of grid."""
  import cv2
  if frame.size!=(1600,940):return None
  rgb=np.asarray(frame.convert('RGB'));x0,y0,x1,y1=100,440,820,580
  area=rgb[y0:y1,x0:x1];hsv=cv2.cvtColor(area,cv2.COLOR_RGB2HSV)
  mask=((hsv[...,0]>=8)&(hsv[...,0]<=40)&(hsv[...,1]>140)&(hsv[...,2]>180)).astype('uint8')
  n,_,stats,_=cv2.connectedComponentsWithStats(mask,8)
  candidates=[]
  for x,y,w,h,count in stats[1:]:
    if not (150<w<330 and 35<h<90 and 2.7<w/h<7 and count>w*h*.60):continue
    box=(int(x+x0),int(y+y0),int(x+x0+w),int(y+y0+h))
    left=(round(box[0]-1.2*w),box[1],round(box[0]-.2*w),box[3])
    if left[0]<0:continue
    white=rgb[left[1]:left[3],left[0]:left[2]]
    if white.size and (white.min(axis=2)>205).mean()>.50:candidates.append((left,box))
  return candidates[0] if len(candidates)==1 else None
def background_skill_drag_target(frame):
  anchors=[(x,y) for x,y in enemy_attack_anchors(frame) if 20<x<830 and 200<y<520]
  if not anchors:return None
  x,y=min(anchors,key=lambda point:abs(point[0]-440))
  return (x,min(590,max(280,y+90)))
def background_cooldown_badge(frame,slot):
  """Outlined pale cooldown glyph at the card's fixed upper-right baseline.

    No portrait-wide OCR: clothing, central bind counts and ready arrows are
    outside this small region. Presence vetoes readiness; it is not a count
    used to authorize haste or infer the remaining cooldown.
    """
  import cv2
  if frame.size!=(1600,940) or slot not in range(6):return False
  cx=round((.057+.0875*slot)*1600)
  tile=np.asarray(frame.crop((cx+25,663,cx+60,698)).convert('RGB'),dtype=np.float32)
  ink=((tile.max(axis=2)-tile.min(axis=2)<65)&(tile.min(axis=2)>135)).astype(np.uint8)
  _,labels,stats,_=cv2.connectedComponentsWithStats(ink,8)
  for index,(x,y,w,h,area) in enumerate(stats[1:],1):
    if not (3<=x<=28 and 2<=y<=10 and 3<=w<=18 and 15<=h<=23 and 25<=area<=200):continue
    glyph=(labels==index).astype(np.uint8)
    rim=(cv2.dilate(glyph,np.ones((5,5),np.uint8))>0)&(glyph==0)
    if rim.any() and float((tile.max(axis=2)[rim]<115).mean())>=.55:return True
  return False
def background_ready_slots(frame):
  import cv2
  rgb=np.asarray(frame.convert('RGB'))
  result=[]
  for slot in range(6):
    cx=round((.057+.0875*slot)*1600)
    tile=rgb[round(.670*940):round(.703*940),cx-25:cx+26]
    orange=(tile[...,0]>185)&(tile[...,1]>100)&(tile[...,1]<235)&(tile[...,2]<100)
    white=tile.min(axis=2)>225
    n,_,stats,_=cv2.connectedComponentsWithStats(white.astype('uint8'),8)
    triangle=any(9<=w<=45 and 4<=h<=20 and 20<=area<=450 and .20<=area/(w*h)<=.80
for x,y,w,h,area in stats[1:])
    if orange.sum()>=50 and triangle and not background_cooldown_badge(frame,slot):result.append(slot)
  return result
def background_skill_effects(text):
  """Conservative active-skill categories; never infer skills from a portrait."""
  t=_compact_ocr_text(text).lower();effects=[]
  all_orbs=any(s in t for s in ('모든드롭','전체드롭','전드롭','全ドロップ'))
  if all_orbs and any(s in t for s in ('변화','변환','바꿉','変化')):
    colors=sum(any(word in t for word in words) for words in (('불','화속성','火'),('물','수속성','水'),('나무','목속성','木'),('빛','광속성','光'),('어둠','암속성','闇')))
    if colors==5:effects.append('five_board')
  if all_orbs and any(s in t for s in ('파괴','破壊')):effects.append('refresh')
  if any(s in t for s in ('바인드','바인딩','각성무효','バインド','覚醒無効')) and any(s in t for s in ('회복','해제','回復')):effects.append('cleanse')
  if any(s in t for s in ('조작시간','操作時間')) and any(s in t for s in ('연장','늘','延長')):effects.append('time')
  if '콤보' in t and any(s in t for s in ('가산','추가')) or 'コンボ加算' in t:effects.append('bonus')
  if any(s in t for s in ('hp를','체력을','hpを')) and any(s in t for s in ('회복','回復')):effects.append('heal')
  return effects
def background_skill_choice(profiles,ready,shortage=False,short_time=False,combo_short=False,bound=False,low_hp=False,used=()):
  priorities=[]
  if bound:priorities.append('cleanse')
  if low_hp:priorities+=['heal','five_board']
  if shortage:priorities+=['five_board','refresh']
  if short_time:priorities.append('time')
  if combo_short:priorities+=['bonus','five_board','refresh']
  for effect in priorities:
    for slot in ready:
      if slot not in used and effect in profiles[slot].get('effects',[]):return slot
  return None
