  def _stage_scroll(self,device,frame,kind,direction=1):
    """Wait for a changed, settled list after a gesture; never credit a swipe."""
    assert_action_active(self)
    bar=crystal_dialog_scrollbar(frame,kind)
    x=1100 if kind=='preview' else 1450
    start,end=(760,400) if direction>0 else (390,750)
    device.swipe(x,start,x,end,650)
    before=np.asarray(frame.crop((440,300,1160,820) if kind=='preview' else (80,240,1490,875)),dtype=np.int16)
    previous=None;previous_bar=None;changed=False;stable=0;current=frame
    heading='출현아이템' if kind=='preview' else '크리스탈획득던전'
    for attempt in range(8):
      assert_action_active(self)
      current=self._nav_pause(device,.12)
      if self._background_header(current)!=heading:raise RuntimeError('목록 스크롤 중 화면이 바뀌었습니다.')
      pixels=np.asarray(current.crop((440,300,1160,820) if kind=='preview' else (80,240,1490,875)),dtype=np.int16)
      current_bar=crystal_dialog_scrollbar(current,kind)
      delta=float(np.abs(pixels-before).mean())
      moved=bool(bar and current_bar and abs(current_bar['top']-bar['top'])>2)
      changed=changed or moved or (bar is None and delta>1.0)
      settled=previous is not None and float(np.abs(pixels-previous).mean())<2.5
      if current_bar and previous_bar:
        settled=abs(current_bar['top']-previous_bar['top'])<=1 and abs(current_bar['bottom']-previous_bar['bottom'])<=1
      stable=stable+1 if settled else 0
      if changed and stable>=2:break
      previous=pixels;previous_bar=current_bar
    if changed and stable<2:raise RuntimeError('목록 스크롤 후 화면이 안정되지 않았습니다.')
    diagnostics=getattr(self,'_background_diagnostics',None)
    if isinstance(diagnostics,dict):
      events=diagnostics.setdefault('list_scrolls',[])
      events.append(dict(kind=kind,direction=direction,changed=changed,captures=attempt+1,thumb=current_bar))
      del events[:-80]
    return current,changed
  def _stage_list_top(self,device,frame,kind='stages'):
    for _ in range(40):
      assert_action_active(self)
      bar=crystal_dialog_scrollbar(frame,kind)
      if bar is None or bar['at_top']:return frame
      frame,moved=self._stage_scroll(device,frame,kind,-1)
      if not moved:raise RuntimeError('목록을 맨 위로 스크롤하지 못했습니다.')
    raise RuntimeError('목록의 시작을 확인하지 못했습니다.')
  def _stage_find_list_stage(self,device,frame,number):
    entries=stage_list_entries(frame,self._stage_listing_tokens(frame),self._stage_db_load())
    target=next((entry for entry in entries if entry['number']==number),None)
    if target is not None:return frame,target['token']
    frame=self._stage_list_top(device,frame)
    for _ in range(40):
      assert_action_active(self)
      entries=stage_list_entries(frame,self._stage_listing_tokens(frame),self._stage_db_load())
      target=next((entry for entry in entries if entry['number']==number),None)
      if target is not None:return frame,target['token']
      bar=crystal_dialog_scrollbar(frame,'stages')
      if bar is not None and bar['at_bottom']:break
      frame,moved=self._stage_scroll(device,frame,'stages')
      if not moved:
        if bar is not None:raise RuntimeError('선택한 스테이지를 찾는 중 스크롤이 움직이지 않았습니다.')
        break
    raise RuntimeError('선택한 스테이지 위치를 다시 확인하지 못했습니다: '+stage_display_name(number))
  def _stage_register_preview(self,device,frame,number,templates,cleared=None):
    if self._background_header(frame)!='출현아이템':raise RuntimeError('출현 아이템 화면을 확인하지 못했습니다.')
    frame=self._stage_list_top(device,frame,'preview')
